import{_ as a,c as t,o as i,ae as n}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Review — with Images (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-customer-review-with-images-gql","title":"Review with Images","description":"A single review with its attached images as a field-selectable Relay connection. Sub-select the images via edges { node { … } }.","query":"query AdminCustomerReview($id: ID!) {\\n  adminCustomerReview(id: $id) {\\n    id\\n    _id\\n    title\\n    comment\\n    rating\\n    status\\n    name\\n    createdAt\\n    updatedAt\\n    product {\\n      id\\n      name\\n      sku\\n    }\\n    customer {\\n      id\\n      name\\n      email\\n    }\\n    images {\\n      edges {\\n        node {\\n          id\\n          path\\n          url\\n        }\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/customers/reviews/21\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCustomerReview\\": {\\n      \\"id\\": \\"/api/admin/customers/reviews/21\\",\\n      \\"_id\\": 21,\\n      \\"title\\": \\"Great product\\",\\n      \\"comment\\": \\"Exactly as described.\\",\\n      \\"rating\\": 5,\\n      \\"status\\": \\"approved\\",\\n      \\"name\\": \\"Jane Doe\\",\\n      \\"createdAt\\": \\"2026-06-01 08:00:00\\",\\n      \\"updatedAt\\": \\"2026-06-20 14:30:00\\",\\n      \\"product\\": {\\n        \\"id\\": 2358,\\n        \\"name\\": \\"Classic Watch Hand\\",\\n        \\"sku\\": \\"SP-001\\"\\n      },\\n      \\"customer\\": {\\n        \\"id\\": 14,\\n        \\"name\\": \\"Jane Doe\\",\\n        \\"email\\": \\"jane@example.com\\"\\n      },\\n      \\"images\\": {\\n        \\"edges\\": [\\n          {\\n            \\"node\\": {\\n              \\"id\\": \\"/api/admin_customer_review_images/4\\",\\n              \\"path\\": \\"review/21/photo.webp\\",\\n              \\"url\\": \\"http://localhost:8000/storage/review/21/photo.webp\\"\\n            }\\n          },\\n          {\\n            \\"node\\": {\\n              \\"id\\": \\"/api/admin_customer_review_images/5\\",\\n              \\"path\\": \\"review/21/back.jpg\\",\\n              \\"url\\": \\"http://localhost:8000/storage/review/21/back.jpg\\"\\n            }\\n          }\\n        ]\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/customers/reviews/review-with-images.md","filePath":"api/graphql-api/admin/customers/reviews/review-with-images.md"}'),d={name:"api/graphql-api/admin/customers/reviews/review-with-images.md"};function r(s,e,o,m,c,h){return i(),t("div",null,e[0]||(e[0]=[n('<h1 id="review-—-with-images-graphql" tabindex="-1">Review — with Images (GraphQL) <a class="header-anchor" href="#review-—-with-images-graphql" aria-label="Permalink to &quot;Review — with Images (GraphQL)&quot;">​</a></h1><p>The same <code>adminCustomerReview</code> query, focused on the attached images. A review&#39;s <code>images</code> are returned as a field-selectable Relay connection — you sub-select them with <code>images { edges { node { … } } }</code> and pick exactly the sub-fields you need, rather than receiving an opaque JSON blob. Over REST the same data comes back as a plain JSON array.</p><p>The <code>id</code> argument is the review IRI (<code>/api/admin/customers/reviews/{id}</code>).</p><h2 id="image-node-fields" tabindex="-1">Image node fields <a class="header-anchor" href="#image-node-fields" aria-label="Permalink to &quot;Image node fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>Image IRI.</td></tr><tr><td><code>path</code></td><td><code>String</code></td><td>Storage path of the image.</td></tr><tr><td><code>url</code></td><td><code>String</code></td><td>Public URL resolved from the storage path.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/graphql-api/admin/customers/reviews/">Reviews overview</a> for how moderation works.</p></div><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',7)]))}const u=a(d,[["render",r]]);export{p as __pageData,u as default};
